async function waitFor(check,millis){const until=Date.now()+millis;let last;while(Date.now()<until){let r;try{r=check();}catch(e){last=e;}if(r&&r.waitError)throw new Error(r.waitError);if(r)return r;await new Promise(r=>setTimeout(r,1000));}throw last||new Error('Timed out waiting for the Windows service.');}
